internal object DuaRuDraft2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_yamani_hajar" to DuaText("Между Рукном Ямани и Хаджаром Асвадом", "Господь наш, дай нам добро в этом мире и добро в будущей жизни и защити нас от наказания Огня.", "Таваф между Йеменским углом и Черным камнем.", "Пророк ﷺ прочитал это в этом месте во время тавафа."),
        "dua_safa_marwa" to DuaText("О Сафе и Марве", "Никто не имеет права на поклонение, кроме Аллаха, одного, без сотоварища. Ему принадлежит власть, и Ему принадлежит хвала, и Он имеет власть над всем. Никто не имеет права на поклонение, кроме одного лишь Аллаха; Он выполнил Свое обещание, помог Своему слуге и в одиночку разгромил союзников.", "Подъем на Сафа лицом к Кибле (три раза).", "Зикр Пророка ﷺ на Сафа и Марва."),
        "dua_arafah" to DuaText("Лучшее дуа дня Арафа", "Никто не имеет права на поклонение, кроме Аллаха, одного, без сотоварища. Ему принадлежит власть, и Ему принадлежит хвала, и Он имеет власть над всем.", "День Арафа — лучшее дуа.", "Лучшее дуа – это дуа Дня Арафа, и лучшие слова – это эти."),
        "dua_takbeer_tashreeq" to DuaText("Такбир-э-Ташрик", "Аллах Величайший, Аллах Величайший. Нет бога, кроме Аллаха. Аллах Величайший, Аллах Величайший, и вся хвала Аллаху.", "После каждой обязательной молитвы от фаджра 9-го зуль-хиджа до Асра 13-го зуль-хиджа.", "Сообщается от Али и Ибн Масуда (RA) — ваджиб по мнению ханафитов."),
        "dua_zamzam" to DuaText("Пить Замзам", "О Аллах, я прошу Тебя о полезных знаниях, обильном обеспечении и исцелении от каждой болезни.", "Выпивая Замзам, делайте дуа за все, что вы намереваетесь.", "Замзам предназначен для того, ради чего его пьют (Ибн Маджа 3062)."),
        "dua_q_ma_khalaqta_batila" to DuaText("Размышления о творении", "Господь наш, Ты не зря все это создал. Слава Тебе, так защити нас от наказания Огня.", "Дуа тех, кто размышляет о сотворении неба и земли.", "Дуа людей понимающих (улуль-албаб)."),
        "dua_q_sami_na_munadiyan" to DuaText("Мы услышали призывающего к вере", "Господь наш, мы услышали призывающего к вере, говорящего: «Веруйте в Господа вашего», и мы уверовали. Господь наш, прости нам грехи наши, удали от нас наши злодеяния и сделай так, чтобы мы умерли с праведниками.", "Дуа за веру и смерть среди праведников.", "Дуа о прощении и хорошем окончании."),
        "dua_q_atina_ma_waadtana" to DuaText("Даруй нам то, что обещал", "Господь наш, даруй нам то, что Ты обещал нам через Своих посланников, и не опозорь нас в День Воскресения. Воистину, Ты не нарушаешь Своего обещания.", "Спасение от позора в День Воскресения.", "В поисках почести в будущей жизни."),
        "dua_q_israfana" to DuaText("Простите наши излишества", "Господь наш, прости нам наши грехи и наши излишества в наших делах, укрепи наши ноги и помоги нам против неверующих людей.", "Дуа сподвижников ранних Пророков.", "Дуа о стойкости и прощении."),
        "dua_q_jamiun_nas" to DuaText("Вы соберете человечество", "Господь наш, Ты непременно соберешь человечество в День, в котором нет сомнения. Воистину, Аллах не нарушает Своего обещания.", "Подтверждение уверенности в День Воскресения.", "Дуа тех, кто твердо укоренен в знании."),
        "dua_q_maash_shahidin" to DuaText("Напишите нам в число свидетелей", "Господь наш, мы уверовали, так запиши нас в число свидетелей.", "Дуа тех, кто признал истину и уверовал.", "Дуа для принятия своей веры."),
        "dua_q_la_tajalna_zalimin" to DuaText("Не с правонарушителями", "Господь наш, не помещай нас в число людей, творящих зло.", "Дуа жителей Аль-Арафа.", "Убежище от участи обидчиков."),
        "dua_q_tawaffana_muslimin" to DuaText("Терпение и смерть по-мусульмански", "Господь наш, пролей на нас терпение и заставь нас умереть как мусульмане.", "Дуа волхвов фараона, когда они уверовали.", "Терпение в испытаниях и окончание веры."),
        "dua_q_la_tajalna_fitnah" to DuaText("Не суд для угнетателей", "На Аллаха мы полагаемся. Господь наш, не делай нас испытанием для людей, творящих зло, и спаси нас Своей милостью от людей неверующих.", "Дуа народа Мусы (AS).", "Дуа для спасения от угнетения и угнетателей."),
        "dua_q_nuh_ma_laysa_li" to DuaText("Дуа Нуха (AS) о прощении.", "Мой Господь, я прибегаю к Тебе, чтобы не просить Тебя о том, о чем я не знаю. И если Ты не простишь меня и не помилуешь меня, я буду в числе проигравших.", "Дуа покаяния Пророка Нуха (AS).", "Урок правильных манер спрашивать."),
        "dua_q_mudkhala_sidq" to DuaText("Вход и выход истины", "Господь мой, сделай так, чтобы я вошел с истиной и вышел с истиной, и даруй мне от Себя поддерживающую власть.", "Прежде чем ввести новую задачу, дом или место.", "Дуа преподавал Пророку ﷺ во время хиджры."),
        "dua_q_la_tadharni_fardan" to DuaText("Дуа Закарии (AS) — Не оставляй меня одного", "Мой Господь, не оставляй меня одного, и Ты лучший из наследников.", "Для тех, кто ищет детей.", "Через это дуа Аллах даровал Яхье (AS)."),
        "dua_q_munzalan_mubarakan" to DuaText("Благословенное место приземления", "Господь мой, позволь мне приземлиться на благословенном месте приземления, и Ты лучший из тех, кто выводит на сушу.", "При переезде в новый дом или остановке где-либо — дуа Нух (AS).", "Дуа на благословение на новом месте."),
        "dua_q_amanna_faghfir" to DuaText("Мы верим, поэтому прости нас", "Господь наш, мы уверовали, так прости нас и помилуй нас, и Ты лучший из милостивых.", "Дуа праведных рабов Аллаха.", "Комплексное дуа о прощении и милосердии."),
        "dua_q_isrif_jahannam" to DuaText("Предотвратите наказание ада", "Господь наш, отврати от нас наказание Ада; действительно, наказание за это всегда цепляет. Действительно, это злое поселение и место жительства.", "Дуа слуг Милосердного (Ибад ар-Рахман).", "Кораническое дуа о спасении от ада."),
        "dua_q_hab_li_hukman" to DuaText("Дуа Ибрагима (AS) — Мудрость и Ранна", "Мой Господь, даруй мне мудрость и присоедини меня к праведникам, даруй мне почетное упоминание среди последующих поколений и сделай меня одним из наследников Сада Блаженства.", "Просят мудрости, общества праведников и Рая.", "Комплексное дуа Ибрагима (AS)."),
        "dua_q_lut_najjini_ahli" to DuaText("Дуа Лут (AS) — Спаси мою семью", "Мой Господь, спаси меня и мою семью от (последствий) того, что они делают.", "Защита своей семьи от окружающей среды зла.", "Защита семьи от зла."),
        "dua_q_sulaiman_awzini" to DuaText("Дуа Сулеймана (AS) для благодарности", "Господь мой, дай мне быть благодарным за Твое благоволение, которое Ты оказал мне и моим родителям, и творить праведные дела, угодные Тебе, и прими меня по Твоей милости в число Твоих праведных рабов.", "За умение быть благодарным за благословения.", "Дуа благодарности Сулеймана (AS)."),
        "dua_q_musa_zalamtu" to DuaText("Дуа Мусы (AS) — Я обидел себя", "Мой Господь, я обидел себя, так прости меня.", "Немедленное раскаяние после ошибки.", "Аллах простил Мусу (AS)."),
        "dua_q_musa_najjini" to DuaText("Дуа Мусы (AS) — Спаси меня от угнетателей", "Мой Господь, спаси меня от нечестивых людей.", "Когда боишься угнетателей.", "Дуа Мусы (AS) при выходе из Египта."),
        "dua_q_lut_unsurni" to DuaText("Дуа Лут (AS) — Помощь против коррупционеров", "Мой Господь, помоги мне против развращающих людей.", "За помощь против тех, кто распространяет коррупцию.", "Дуа тех, кто твердо стоит на истине."),
        "dua_q_hab_li_salihin" to DuaText("Дуа Ибрахима (AS) за праведного ребенка", "Господь мой, даруй мне (ребенка) из числа праведных.", "Просить о праведных детях.", "Благодаря этому дуа было даровано Исмаилу (AS)."),
        "dua_q_wasita_kulla_shay" to DuaText("Дуа Ангелов, Несущих Трон", "Господь наш, Ты охватываешь все милостью и знанием, поэтому прости тех, кто кается и следует Твоим путем, и защити их от наказания Ада.", "Ангелы, несущие Трон, совершают это дуа за верующих.", "Произносится с намерением быть включенным в дуа ангелов."),
        "dua_q_ikhwanina" to DuaText("Для наших братьев, которые были до нас", "Господь наш, прости нас и наших братьев, которые предшествовали нам в вере, и не вложи в наши сердца злобы к верующим. Господь наш, Ты действительно Добрый и Милосердный.", "Дуа за верующих, пришедших раньше, и за чистое сердце.", "Дуа за благородных сподвижников (RA) и первых верующих."),
        "dua_q_alayka_tawakkalna" to DuaText("Мы полагаемся на вас (Ибрагим А.С.)", "Господь наш, на Тебя мы полагаемся, к Тебе обращаемся и к Тебе возвращение. Господь наш, не сделай нас испытанием для неверующих и прости нас. Господь наш, Ты поистине Всемогущий, Мудрый.", "Дуа Ибрагима (AS) и его сподвижников.", "Дуа упования на Аллаха и обращения к Нему."),
        "dua_q_atmim_nurana" to DuaText("Совершенствуйте наш свет", "Господь наш, соверши для нас свет наш и прости нас. Воистину, Ты обладаешь властью над всем сущим.", "Дуа верующих в День Воскресения.", "Прошу света на Сирате."),
        "dua_q_asiya_baytan" to DuaText("Дуа Асии — Дом в Джане", "Господь мой, построй для меня возле Тебя дом в Раю, спаси меня от фараона и его дел, и сохрани меня от людей, творящих зло.", "Дуа Асии, жены фараона.", "Аллах сделал ее примером для верующих."),
        "dua_adhan_response" to DuaText("Ответ на Азан", "Нет мощи и мощи, кроме как у Аллаха.", "Повторите то, что говорит муэдзин; в «Хайя алас-салах» и «Хайя аляль-фалах» говорят это.", "Кто откликнется от сердца, тот войдет в Рай."),
        "dua_adhan_shahadah" to DuaText("После шахады Муаззина", "И я также свидетельствую, что никто не имеет права на поклонение, кроме Аллаха, одного, без сотоварища, и что Мухаммад ﷺ — Его слуга и Посланник. Я доволен Аллахом как Господом, Мухаммадом ﷺ как Посланником и Исламом как религией.", "Выслушав свидетельство веры муэдзина.", "Его грехи прощены."),
        "dua_istiftah_baid" to DuaText("Вступительное дуа: отдали меня от грехов", "О Аллах, отдали меня от моих грехов, как Ты отдалил восток от запада. О Аллах, очисти меня от грехов, как белая одежда очищается от грязи. О Аллах, смой мои грехи водой, снегом и градом.", "После вступительного такбира (можно произносить и вместо саны).", "Пророк ﷺ читал это между такбиром и чтением."),
        "dua_hamdan_kathiran" to DuaText("Обильная похвала после Руку", "Господь наш, Тебе принадлежит хвала – обильная, чистая и благословенная хвала.", "После подъема из руку вместе с Раббаной лакал-хамд.", "Более тридцати ангелов боролись за то, чтобы первыми записать это."),
        "dua_subbuhun_quddus" to DuaText("Суббухун Куддус (Руку и Суджуд)", "(Аллах) Самый Прославленный, Самый Святой, Господь ангелов и Духа (Джибриль).", "В руку и суджуде.", "Пророк ﷺ читал это в руку и суджуде."),
        "dua_sujood_dhanbi_kullah" to DuaText("В Суджуде: Прости все мои грехи", "О Аллах, прости мне все мои грехи – малые и великие, первые и последние, явные и скрытые.", "В суджуде.", "Простирание – это место, где получают ответы на дуа."),
        "dua_sujood_ridaka" to DuaText("Убежище в ваше удовольствие", "О Аллах, я прибегаю к Твоему удовольствию от Твоего гнева, к Твоему прощению от Твоего наказания, и я прибегаю к Тебе от Тебя. Я не могу полностью восхвалить Тебя; Ты такой, каким Ты похвалил Себя.", "В суджуде — Аиша (RA) услышала, как Пророк ﷺ сказал это.", "Суджуд-дуа Пророка ﷺ."),
        "dua_tashahhud" to DuaText("Ташаххуд (Ат-Тахийят)", "Все словесные, физические и финансовые акты поклонения предназначены для Аллаха. Мир тебе, о Пророк, милость Аллаха и Его благословение. Мир нам и праведным рабам Аллаха. Я свидетельствую, что никто не имеет права на поклонение, кроме Аллаха, и свидетельствую, что Мухаммад ﷺ — Его слуга и Посланник.", "На каждом сеансе — передал Абдулла ибн Масуд (RA) (ханафитская практика).", "Пророк ﷺ учил этому как суре Корана."),
    )
}
